import android.content.Context;
import android.database.sqlite.SQLiteDatabase;
import android.database.sqlite.SQLiteOpenHelper;

public class DatabaseHelper extends SQLiteOpenHelper {
	private static final String DATABASE_NAME = "BankingApp";
	private static final int DATABASE_VERSION = 1;

	private static final String TABLE_ACCOUNTS = "accounts";
	private static final String COLUMN_ACCOUNT_ID = "id";
	private static final String COLUMN_ACCOUNT_NAME = "name";
	private static final String COLUMN_ACCOUNT_EMAIL = "email";
	private static final String COLUMN_ACCOUNT_PASSWORD = "password";
	private static final String COLUMN_ACCOUNT_BALANCE = "balance";

	private static final String TABLE_TRANSACTIONS = "transactions";
	private static final String COLUMN_TRANSACTION_ID = "id";
	private static final String COLUMN_TRANSACTION_ACCOUNT_ID = "account_id";
	private static final String COLUMN_TRANSACTION_AMOUNT = "amount";
	private static final String COLUMN_TRANSACTION_TYPE = "type";
	private static final String COLUMN_TRANSACTION_DATE = "date";
	private static final String COLUMN_TRANSACTION_DESCRIPTION = "description";

	public DatabaseHelper(Context context) {
		super(context, DATABASE_NAME, null, DATABASE_VERSION);
	}

	@Override
	public void onCreate(SQLiteDatabase db) {
		String createAccountsTable = "CREATE TABLE " + TABLE_ACCOUNTS + "(" +
				COLUMN_ACCOUNT_ID + " INTEGER PRIMARY KEY," +
				COLUMN_ACCOUNT_NAME + " TEXT," +
				COLUMN_ACCOUNT_EMAIL + " TEXT," +
				COLUMN_ACCOUNT_PASSWORD + " TEXT," +
				COLUMN_ACCOUNT_BALANCE + " INTEGER)";
		db.execSQL(createAccountsTable);

		String createTransactionsTable = "CREATE TABLE " + TABLE_TRANSACTIONS + "(" +
				COLUMN_TRANSACTION_ID + " INTEGER PRIMARY KEY," +
				COLUMN_TRANSACTION_ACCOUNT_ID + " INTEGER," +
				COLUMN_TRANSACTION_AMOUNT + " INTEGER," +
				COLUMN_TRANSACTION_TYPE + " TEXT," +
				COLUMN_TRANSACTION_DATE + " TEXT," +
				COLUMN_TRANSACTION_DESCRIPTION + " TEXT)";
		db.execSQL(createTransactionsTable);
	}

	@Override
	public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
		db.execSQL("DROP TABLE IF EXISTS " + TABLE_ACCOUNTS);
		db.execSQL("DROP TABLE IF EXISTS " + TABLE_TRANSACTIONS);
		onCreate(db);
	}
}
