import android.content.Intent;
import android.os.Bundle;
import android.view.View;
import android.widget.EditText;
import android.widget.Toast;
import androidx.appcompat.app.AppCompatActivity;

import java.util.Calendar;

public class TransferActivity extends AppCompatActivity {
	private DatabaseHelper databaseHelper;
	private Account currentAccount;

	@Override
	protected void onCreate(Bundle savedInstanceState) {
		super.onCreate(savedInstanceState);
		setContentView(R.layout.activity_transfer);
		databaseHelper = new DatabaseHelper(this);
		currentAccount = (Account) getIntent().getSerializableExtra("account");
	}

	public void transferMoney(View view) {
		EditText amountEditText = findViewById(R.id.amountEditText);
		EditText toAccountEditText = findViewById(R.id.toAccountEditText);

		String amountStr = amountEditText.getText().toString();
		String toAccountStr = toAccountEditText.getText().toString();

		if (amountStr.isEmpty() || toAccountStr.isEmpty()) {
			Toast.makeText(this, "Please enter amount and account number", Toast.LENGTH_SHORT).show();
			return;
		}

		int amount = Integer.parseInt(amountStr);
		if (amount > currentAccount.getBalance()) {
			Toast.makeText(this, "Insufficient funds", Toast.LENGTH_SHORT).show();
			return;
		}

		// Create transaction
		Calendar calendar = Calendar.getInstance();
		String date = calendar.getTime().toString();
		Transaction transaction = new Transaction(0, currentAccount.getId(), amount, "transfer", date, "Transfer to " + toAccountStr);
		databaseHelper.addTransaction(transaction);

		// Update account balance
		currentAccount.setBalance(currentAccount.getBalance() - amount);
		databaseHelper.updateAccount(currentAccount);

		Toast.makeText(this, "Transfer successful", Toast.LENGTH_SHORT).show();
		finish(); // go back to dashboard
	}
}
