	public Account getAccountByEmail(String email) {
		String query = "SELECT * FROM " + TABLE_ACCOUNTS + " WHERE " + COLUMN_ACCOUNT_EMAIL + " = ?";
		SQLiteDatabase db = getReadableDatabase();
		Cursor cursor = db.rawQuery(query, new String[]{email});
		if (cursor.moveToFirst()) {
			int id = cursor.getInt(cursor.getColumnIndex(COLUMN_ACCOUNT_ID));
			String name = cursor.getString(cursor.getColumnIndex(COLUMN_ACCOUNT_NAME));
			String emailCursor = cursor.getString(cursor.getColumnIndex(COLUMN_ACCOUNT_EMAIL));
			String password = cursor.getString(cursor.getColumnIndex(COLUMN_ACCOUNT_PASSWORD));
			int balance = cursor.getInt(cursor.getColumnIndex(COLUMN_ACCOUNT_BALANCE));
			return new Account(id, name, emailCursor, password, balance);
		}
		return null;
	}

	public boolean isEmailExist(String email) {
		String query = "SELECT * FROM " + TABLE_ACCOUNTS + " WHERE " + COLUMN_ACCOUNT_EMAIL + " = ?";
		SQLiteDatabase db = getReadableDatabase();
		Cursor cursor = db.rawQuery(query, new String[]{email});
		return cursor.getCount() > 0;
	}

