				COLUMN_ACCOUNT_EMAIL + ", " +
				COLUMN_ACCOUNT_PASSWORD + ", " +
				COLUMN_ACCOUNT_BALANCE + ")" +
				" VALUES (?, ?, ?, ?)";
		db.execSQL(query, new Object[]{
				account.getName(),
				account.getEmail(),
				account.getPassword(),
				account.getBalance()
		});
	}

	public List<Transaction> getTransactionHistory(int accountId) {
		String query = "SELECT * FROM " + TABLE_TRANSACTIONS + " WHERE " + COLUMN_TRANSACTION_ACCOUNT_ID + " = ?" +
				" ORDER BY " + COLUMN_TRANSACTION_DATE + " DESC";
		SQLiteDatabase db = getReadableDatabase();
		Cursor cursor = db.rawQuery(query, new String[]{String.valueOf(accountId)});
		List<Transaction> transactions = new ArrayList<>();
		while (cursor.moveToNext()) {
			int id = cursor.getInt(cursor.getColumnIndex(COLUMN_TRANSACTION_ID));
			int accId = cursor.getInt(cursor.getColumnIndex(COLUMN_TRANSACTION_ACCOUNT_ID));
			int amount = cursor.getInt(cursor.getColumnIndex(COLUMN_TRANSACTION_AMOUNT));
			String type = cursor.getString(cursor.getColumnIndex(COLUMN_TRANSACTION_TYPE));
			String date = cursor.getString(cursor.getColumnIndex(COLUMN_TRANSACTION_DATE));
			String description = cursor.getString(cursor.getColumnIndex(COLUMN_TRANSACTION_DESCRIPTION));
			transactions.add(new Transaction(id, accId, amount, type, date, description));
