   public class AccountDB {
		private static final String DB_NAME = "Bank.db";
		private static final String TABLE_NAME = "accounts";
		private static final String COL_ID = "id";
		private static final String COL_ACCOUNT = "account";
		private static final String COL_PIN = "pin";
		private static final String COL_BALANCE = "balance";

		private Context context;
		private SQLiteOpenHelper helper;

		public AccountDB(Context context) {
			this.context = context;
			helper = new SQLiteOpenHelper(context, DB_NAME, null, 1) {
				@Override
				public void onCreate(SQLiteDatabase db) {
					db.createTable(TABLE_NAME, true, createAccountColumns());
					db.setForeignKeyConstraintsEnabled(false);
				}

				private String createAccountColumns() {
					StringBuilder sb = new StringBuilder();
					sb.append("id INTEGER PRIMARY KEY");
					sb.append(", account TEXT");
					sb.append(", pin TEXT");
					sb.append(", balance INTEGER");
					return sb.toString();
				}

				@Override
				public void onUpgrade(SQLiteDatabase db, int oldVersion, int newVersion) {
					db.execSQL("drop table if exists " + TABLE_NAME);
					db.createTable(TABLE_NAME, true, createAccountColumns());
				}
			};
		}

		private void createDatabase() {
			helper.getWritableDatabase();
		}

		public long insertAccount(String account, String pin, int balance) {
			createDatabase();
			SQLiteDatabase db = helper.getWritableDatabase();
			ContentValues values = new ContentValues();
			values.put COL_ACCOUNT, account;
			values.put COL_PIN, pin;
			values.put COL_BALANCE, balance;
			return db.insert(TABLE_NAME, null, values);
		}

		public int updateAccount(String account, String pin, int balance) {
			createDatabase();
			SQLiteDatabase db = helper.getWritableDatabase();
			ContentValues values = new ContentValues();
			values.put COL_PIN, pin;
			values.put COL_BALANCE, balance;
			return db.update(TABLE_NAME, values, COL_ACCOUNT + " = ?", new String[]{account});
		}

		public Account getAccount(String account) {
			createDatabase();
			SQLiteDatabase db = helper.getWritableDatabase();
			Cursor cursor = db.query(TABLE_NAME, new String[]{COL_ID, COL_ACCOUNT, COL_PIN, COL_BALANCE}, COL_ACCOUNT + " = ?", new String[]{account}, null);
			if (cursor == null || cursor.moveToFirst()) {
				int id = cursor.getInt(0);
				String acc = cursor.getString(1);
				String pin = cursor.getString(2);
				int bal = cursor.getInt(3);
				cursor.close();
				return new Account(id, acc, pin, bal);
			}
			return null;
		}

		public List<Account> getAllAccounts() {
			createDatabase();
			SQLiteDatabase db = helper.getWritableDatabase();
			List<Account> accounts = new ArrayList<>();
			cursor = db.query(TABLE_NAME, new String[]{COL_ID, COL_ACCOUNT, COL_PIN, COL_BALANCE}, null, null, null, null, null);
			if (cursor != null && cursor.moveToFirst()) {
				while (!cursor.isAfterLast()) {
					int id = cursor.getInt(0);
					String acc = cursor.getString(1);
					String pin = cursor.getString(2);
					int bal = cursor.getInt(3);
					accounts.add(new Account(id, acc, pin, bal));
					cursor.moveToNext();
				}
				cursor.close();
			}
			return accounts;
		}

		public void deleteAccount(int id) {
			createDatabase();
			SQLiteDatabase db = helper.getWritableDatabase();
			db.delete(TABLE_NAME, COL_ID + " = ?", new String[]{String.valueOf(id)});
		}
   }

