Here's a C example for AF_PACKET ring buffer:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/ether.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <linux/if_packet.h>
#include <linux/if_ether.h>
#include <arpa/inet.h>

#define BUFFER_SIZE (1 << 20) // 1MB ring buffer
#define FRAME_SIZE 2048

struct flow_key {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t proto;
};

struct flow_record {
    struct flow_key key;
    uint64_t bytes;
    uint64_t packets;
    uint32_t last_seen; // timestamp in seconds
    // other fields as needed
};

#define FLOW_TABLE_SIZE (1 << 20) // 1M entries
struct flow_record flow_table[FLOW_TABLE_SIZE];

// Simple hash function for flow key
uint32_t flow_hash(struct flow_key *key) {
    uint32_t hash = key->src_ip ^ key->dst_ip;
    hash ^= (key->src_port << 16) | key->dst_port;
    hash ^= key->proto;
    return hash;
}

// Lookup or create flow
struct flow_record* get_flow(struct flow_key *key) {
    uint32_t hash = flow_hash(key) & (FLOW_TABLE_SIZE - 1);
    // Linear probing for simplicity
    while (1) {
        struct flow_record *flow = &flow_table[hash];
        if (flow->key.src_ip == key->src_ip &&
            flow->key.dst_ip == key->dst_ip &&
            flow->key.src_port == key->src_port &&
            flow->key.dst_port == key->dst_port &&
            flow->key.proto == key->proto) {
            return flow;
        }
        if (flow->key.src_ip == 0) { // empty slot
            // Initialize new flow
            flow->key = *key;
            flow->bytes = 0;
            flow->packets = 0;
            flow->last_seen = time(NULL);
            return flow;
        }
        hash = (hash + 1) & (FLOW_TABLE_SIZE - 1);
    }
}

int main() {
    int sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        return 1;
    }

    // Set up ring buffer
    struct tpacket_req req;
    memset(&req, 0, sizeof(req));
    req.tp_block_size = BUFFER_SIZE / 2;
    req.tp_block_nr = 2;
    req.tp_frame_size = FRAME_SIZE;
    req.tp_frame_nr = (BUFFER_SIZE / 2) / FRAME_SIZE;
    if (setsockopt(sockfd, SOL_PACKET, PACKET_RX_RING, &req, sizeof(req)) < 0) {
        perror("setsockopt");
        close(sockfd);
        return 1;
    }

    // Map ring buffer
    void *buffer = mmap(NULL, BUFFER_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, sockfd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(sockfd);
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for packets
        struct pollfd pfd = { .fd = sockfd, .events = POLLIN };
        poll(&pfd, 1, 1000); // 1 second timeout

        if (pfd.revents & POLLIN) {
            struct tpacket_hdr *hdr;
            unsigned char *data;
            int len;

            // Process all available packets
            hdr = (struct tpacket_hdr *)buffer;
            while (hdr->tp_status == TP_STATUS_USER) {
                data = (unsigned char *)buffer + hdr->tp_mac;
                len = hdr->tp_len;

                // Parse packet
                struct ethhdr *eth = (struct ethhdr *)data;
                if (ntohs(eth->h_proto) == ETH_P_IP) {
                    struct iphdr *ip = (struct iphdr *)(data + sizeof(struct ethhdr));
                    uint16_t ip_len = ntohs(ip->tot_len);
                    uint8_t proto = ip->protocol;
                    uint32_t src_ip = ip->saddr;
                    uint32_t dst_ip = ip->daddr;

                    if (proto == IPPROTO_TCP) {
                        struct tcphdr *tcp = (struct tcphdr *)(data + sizeof(struct ethhdr) + sizeof(struct iphdr));
                        uint16_t src_port = ntohs(tcp->source);
                        uint16_t dst_port = ntohs(tcp->dest);

                        struct flow_key key = {src_ip, dst_ip, src_port, dst_port, proto};
                        struct flow_record *flow = get_flow(&key);
                        flow->bytes += len;
                        flow->packets++;
                        flow->last_seen = time(NULL);
                    } else if (proto == IPPROTO_UDP) {
                        struct udphdr *udp = (struct udphdr *)(data + sizeof(struct ethhdr) + sizeof(struct iphdr));
                        uint16_t src_port = ntohs(udp->source);
                        uint16_t dst_port = ntohs(udp->dest);

                        struct flow_key key = {src_ip, dst_ip, src_port, dst_port, proto};
                        struct flow_record *flow = get_flow(&key);
                        flow->bytes += len;
                        flow->packets++;
                        flow->last_seen = time(NULL);
                    }
                }

                hdr->tp_status = TP_STATUS_KERNEL;
                hdr = (struct tpacket_hdr *)((unsigned char *)hdr + hdr->tp_next_offset);
            }
        }

        // Periodically expire old flows
        static uint32_t last_expire = 0;
        uint32_t now = time(NULL);
        if (now - last_expire > 30) { // every 30 seconds
            last_expire = now;
            for (int i = 0; i < FLOW_TABLE_SIZE; i++) {
                if (flow_table[i].key.src_ip != 0 && now - flow_table[i].last_seen > 30) {
                    // Expire flow
                    flow_table[i].key.src_ip = 0; // mark as empty
                }
            }
        }
    }

    munmap(buffer, BUFFER_SIZE);
    close(sockfd);
    return 0;
}
