**Step 2: Producer Code**

We'll create a producer that sends messages to a topic `monitoring_topic` with a timestamp.

```java
import org.apache.kafka.clientsproducer.KafkaProducer;
import org.apache.kafka.clientsproducer.KafkaProducerConfig;
import org.apache.kafka.common.serialization.Serializer;

import java.util.Properties;
import java.util.concurrent.TimeUnit;

public class MessageProducer {
    private static final String TOPIC = "monitoring_topic";
    private static final String BOOTSTRAP_SERVERS = "localhost:9092"; // adjust accordingly

    public static void main(String[] args) {
        Properties properties = new Properties();
        properties.put(KafkaProducerConfig.BOOTSTRAP_SERVERS_CONFIG, BOOTSTRAP_SERVERS);
        properties.put(KafkaProducerConfig.CLIENT_ID_CONFIG, "producer");
        properties.put(KafkaProducerConfig.KEYSerializer_CLASS_CONFIG, StringSerializer.class.getName());
        properties.put(KafkaProducerConfig.VALUESerializer_CLASS_CONFIG, MessageSerializer.class.getName());

		KafkaProducer<String, MonitoringMessage> producer = new KafkaProducer<>(properties);

		// Send 100 messages
		for (int i = 0; i < 100; i++) {
            MonitoringMessage message = new MonitoringMessage();
            message.setMessage("message " + i);
            message.setTimestamp(System.currentTimeMillis());

            producer.send(new ProducerRecord<>(TOPIC, message.getMessage(), message));
        }

		// Wait for messages to be sent
		producer.flush();
		producer.close();
	}
}

class MessageSerializer implements Serializer<MonitoringMessage> {
    @Override
    public byte[] serialize(String topic, MonitoringMessage message) {
        // Implement serialization (e.g., using JSON or Avro)
        // For simplicity, we'll use a simple string representation
        return (message.getMessage() + ":" + message.getTimestamp()).getBytes();
    }
}

class MonitoringMessage {
    private String message;
    private long timestamp;

    // Getters and setters
    public String getMessage() { return message; }
    public void setMessage(String message) { this.message = message; }
    public long getTimestamp() { return timestamp; }
    public void setTimestamp(long timestamp) { this.timestamp = timestamp; }
}
