**Step 3: Consumer Code**

The consumer will read messages and record the latency.

```java
import org.apache.kafka.clients.consumer.ConsumerConfig;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import org.apache.kafka.clients.consumer.ConsumerRecords;
import org.apache.kafka.common.TopicPartition;
import org.apache.kafka.common.serialization.Deserializer;

import java.util.Collections;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

public class MessageConsumer {
    private static final String TOPIC = "monitoring_topic";
    private static final String BOOTSTRAP_SERVERS = "localhost:9092"; // adjust accordingly

    public static void main(String[] args) {
        Properties properties = new Properties();
        properties.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, BOOTSTRAP_SERVERS);
        properties.put(ConsumerConfig.CLIENT_ID_CONFIG, "consumer");
        properties.put(ConsumerConfig.GROUP_ID_CONFIG, "monitoring-group");
        properties.put(ConsumerConfig.KEYDeserializer_CLASS_CONFIG, StringDeserializer.class.getName());
        properties.put(ConsumerConfig.VALUEDeserializer_CLASS_CONFIG, MessageDeserializer.class.getName());

		KafkaConsumer<String, MonitoringMessage> consumer = new KafkaConsumer<>(properties);
		consumer.subscribe(Collections.singleton(TOPIC));

		// Start consuming
		while (true) {
            ConsumerRecords<String, MonitoringMessage> records = consumer.poll(100, TimeUnit.MILLISECONDS);
            for (ConsumerRecord<String, MonitoringMessage> record : records) {
                long latency = System.currentTimeMillis() - record.value().getTimestamp();
                // Here we would log or send the latency to a monitoring system
                System.out.println("Message: " + record.key() + " with latency: " + latency + " ms");
            }
		}
	}
}

class MessageDeserializer implements Deserializer<MonitoringMessage> {
    @Override
    public MonitoringMessage deserialize(String topic, byte[] bytes) {
        // Parse the byte array to MonitoringMessage
        // For simplicity, we split by colon
        String[] parts = new String(bytes).split(":");
        MonitoringMessage message = new MonitoringMessage();
        message.setMessage(parts[0]);
        message.setTimestamp(Long.parseLong(parts[1]));
        return message;
    }
}
